insert into public.substancia_aprovacao_ue (substancia_id, celex, ato_data, ato_tipo, expiry_novo, anexo_parte, anexo_linha, risk_assessment, candidate_for_substitution, citacao_literal, ato_lido, capturado_em) select id, '32024R2186', '2026-09-02', 'RENEWAL', '2039-10-31', 'B', '170', 'FINALISED', null, 'COMMISSION IMPLEMENTING REGULATION (EU) 2024/2186 of 3 September 2024 renewing the approval of the active substance captan in accordance with Regulation (EC) No 1107/2009 of the European Parliament and of the Council, and amending Commission Implementing Regulation (EU) No 540/2011 | The approval of the active substance captan, as specified in Annex I to this Regulation, is renewed subject to the conditions laid down in that Annex. | The approval of the active substance captan, as set out in Part A of the Annex to Implementing Regulation (EU) No 540/2011, expires on 15 November 2024. | Date of approval
insert into public.substancia_aprovacao_ue (substancia_id, celex, ato_data, ato_tipo, expiry_novo, anexo_parte, anexo_linha, risk_assessment, candidate_for_substitution, citacao_literal, ato_lido, capturado_em) select id, '32024R2198', '2026-09-02', 'RENEWAL', '2039-10-31', 'B — o ato acrescenta a entrada de folpet na Parte B do Anexo do Reg. 540/2011 e, no mesmo ato, suprime a entrada 146 da Parte A. Antes do ato a substancia estava na Parte A.', '172 (nova entrada na Parte B). A linha suprimida na Parte A e a 146.', 'FINALISED', false, 'COMMISSION IMPLEMENTING REGULATION (EU) 2024/2198 of 4 September 2024 renewing the approval of the active substance folpet in accordance with Regulation (EC) No 1107/2009 of the European Parliament and of the Council, and amending Commission Implementing Regulation (EU) No 540/2011 | The approval of the active substance folpet, as set out in Part A of the Annex to Implementing Regulation (EU) No 540/2011 expires on 15 February 2025. | The approval of the active substance folpet, as specified in Annex I to this Regulation, is renewed, subject to the conditions laid down in that Annex. | The Annex to Implementing Regulation (EU) No 540/2011 is amended in accordance with Annex II to this Regulation. | in Part A, entry 146 on folpet is deleted; | in Part B, the following entry is added: | ‘172 Folpet CAS No: 133-07-3 CIPAC No: 75 | 1 November 2024 | 31 October 2039 | On 12 July 2023, the Authority communicated to the Commission its conclusion ( 7 ) on whether folpet can be expected to meet the approval criteria provided for in Article 4 of Regulation (EC) No 1107/2009. | It has been established with respect to one or more representative uses of at least one plant protection product containing the active substance folpet that the approval criteria provided for in Article 4 of Regulation (EC) No 1107/2009 are satisfied. | It is therefore appropriate to renew the approval of folpet. | Although the risk assessment for the renewal of the approval of the active substance folpet is based on a limited number of representative uses, this does not restrict the uses for which plant protection products containing folpet may be authorised. It is therefore appropriate not to maintain the restriction to use folpet as a fungicide. | Furthermore, to finalise the consumer exposure assessment', true, '2026-09-02T00:00:00Z' from public.substancia_ativa where nome_canonico = 'FOLPET' on conflict (substancia_id, celex) do nothing;
