insert into public.resistencia_confirmada (pais, especie, especie_comum, cultura_declarada, mecanismo, primeiro_caso_ano, regioes, resistencia_multipla, autoridade, fonte_url, citacao_literal, capturado_em) values ('IT', 'Alisma plantago-aquatica L.', 'Mesolaccia comune, piantaggine acquatica, cinquenervi d''acqua, cucchiaio', 'riso (arroz)', 'ALS (gruppo B) — literal: "erbicidi inibitori dell''ALS (gruppo B)"', 1994, array['Piemonte', 'Lombardia']::text[], true, 'GIRE (CNR-IPSP)', 'http://gire.mlib.cnr.it/index.php?sel=schedeSpecie/Alisma', '"Tipo di resistenza: popolazioni resistenti agli erbicidi inibitori dell''ALS (gruppo B) con resistenza incrociata alle solfoniluree e alle triazolopirimidine. Primo caso accertato nel 1994. Regioni interessate: Piemonte, Lombardia."', '2026-09-02T00:00:00Z') on conflict (pais, especie, mecanismo, cultura_declarada, autoridade) do nothing;
insert into public.resistencia_confirmada (pais, especie, especie_comum, cultura_declarada, mecanismo, primeiro_caso_ano, regioes, resistencia_multipla, autoridade, fonte_url, citacao_literal, capturado_em) values ('IT', 'Amaranthus hybridus (sinonimi na ficha: A. patulus, A. chlorostachys, A. quitensis, A. cruentus)', 'Amaranto ibrido, amaranto a spiga verde', 'soia (soja)', 'A ficha NAO nomeia o mecanismo (nao escreve ALS nem gruppo B). Declara literalmente resistencia cruzada a duas familias quimicas: "cross-resistenti alle solfoniluree (thifensulfuron-methyl) ed agli imidazolinoni (imazamox)". Qual mecanismo o GIRE atribui a esta populacao, nesta pagina: NAO SEI.', 2017, array['Veneto', 'Friuli Venezia Giulia']::text[], true, 'GIRE (CNR-IPSP)', 'http://gire.mlib.cnr.it/index.php?sel=schedeSpecie/Amaranthus_hyb', '"Tipo di resistenza: popolazioni cross-resistenti alle solfoniluree (thifensulfuron-methyl) ed agli imidazolinoni (imazamox). Primo caso 2017. Regioni interessate: Veneto, Friuli Venezia Giulia."', '2026-09-02T00:00:00Z') on conflict (pais, especie, mecanismo, cultura_declarada, autoridade) do nothing;
insert into public.resistencia_confirmada (pais, especie, especie_comum, cultura_declarada, mecanismo, primeiro_caso_ano, regioes, resistencia_multipla, autoridade, fonte_url, citacao_literal, capturado_em) values ('IT', 'Amaranthus palmeri S. Wats', 'Amaranto (o titulo da pagina sai como "Scheda per Amaranto, GIRE"; o unico nome comum listado e "Amaranto")', 'soia (soja)', 'ALS (gruppo B) — literal: "erbicidi inibitori dell''ALS (gruppo B)"', 2018, array['Veneto']::text[], true, 'GIRE (CNR-IPSP)', 'http://gire.mlib.cnr.it/index.php?sel=schedeSpecie/Amaranthus_palm', '"Il primo caso di resistenza agli erbicidi inibitori dell''ALS (gruppo B) e stato accertato nel 2018 in Veneto."', '2026-09-02T00:00:00Z') on conflict (pais, especie, mecanismo, cultura_declarada, autoridade) do nothing;
insert into public.resistencia_confirmada (pais, especie, especie_comum, cultura_declarada, mecanismo, primeiro_caso_ano, regioes, resistencia_multipla, autoridade, fonte_url, citacao_literal, capturado_em) values ('IT', 'Amaranthus retroflexus L.', 'Amaranto comune, blito', 'soia (soja)', 'O corpo do texto NAO nomeia o mecanismo: fala so da familia quimica, literal "resistenti alle solfoniluree (thifensulfuron-methyl)". Logo abaixo da secao ha um link de mapa rotulado "Mappa (dicotiledoni estive) ALS" — e rotulo de link, nao frase do corpo, e por isso nao trato como mecanismo declarado no texto. O mecanismo afirmado no corpo desta ficha: NAO SEI.', 2003, array['Veneto', 'Emilia Romagna', 'Friuli Venezia Giulia']::text[], true, 'GIRE (CNR-IPSP)', 'http://gire.mlib.cnr.it/index.php?sel=schedeSpecie/Amaranthus', '"In Italia sono state segnalate alcune popolazioni resistenti alle solfoniluree (thifensulfuron-methyl). Primo caso accertato nel 2003."', '2026-09-02T00:00:00Z') on conflict (pais, especie, mecanismo, cultura_declarada, autoridade) do nothing;
insert into public.resistencia_confirmada (pais, especie, especie_comum, cultura_declarada, mecanismo, primeiro_caso_ano, regioes, resistencia_multipla, autoridade, fonte_url, citacao_literal, capturado_em) values ('IT', 'Amaranthus tuberculatus (sinonimi: A. rudis, A. tamariscina)', 'Amaranto tubercolato', 'soia (soja)', 'A ficha NAO nomeia o mecanismo nem o grupo HRAC. Descreve os quimicos: solfoniluree (tifensulfuron-metile) e imidazolinoni (imazamox). NAO SEI se a ficha classifica isso como ALS/grupo B — ela nao escreve isso.', 2010, array['Veneto', 'Friuli Venezia Giulia', 'Emilia Romagna']::text[], true, 'GIRE (CNR-IPSP)', 'http://gire.mlib.cnr.it/index.php?sel=schedeSpecie/Amaranthus_tub', '''popolazioni cross-resistenti alle solfoniluree (tifensulfuron-metile) ed agli imidazolinoni (imazamox)'' — GIRE (CNR), ficha Amaranthus tuberculatus.', '2026-09-02T00:00:00Z') on conflict (pais, especie, mecanismo, cultura_declarada, autoridade) do nothing;
insert into public.resistencia_confirmada (pais, especie, especie_comum, cultura_declarada, mecanismo, primeiro_caso_ano, regioes, resistencia_multipla, autoridade, fonte_url, citacao_literal, capturado_em) values ('IT', 'Ammania coccinea Rottb', 'Ammania arrossata', 'riso (arroz)', 'Inibidores da ALS (grupo B) — a ficha nomeia explicitamente: ''erbicidi inibitori dell''ALS (gruppo B)'', com resistencia cruzada a solfoniluree e triazolopirimidine.', 2018, array['Piemonte', 'Lombardia']::text[], true, 'GIRE (CNR-IPSP)', 'http://gire.mlib.cnr.it/index.php?sel=schedeSpecie/Ammania', '''popolazioni resistenti agli erbicidi inibitori dell''ALS (gruppo B) con resistenza incrociata alle solfoniluree'' — GIRE (CNR), ficha Ammania coccinea.', '2026-09-02T00:00:00Z') on conflict (pais, especie, mecanismo, cultura_declarada, autoridade) do nothing;
insert into public.resistencia_confirmada (pais, especie, especie_comum, cultura_declarada, mecanismo, primeiro_caso_ano, regioes, resistencia_multipla, autoridade, fonte_url, citacao_literal, capturado_em) values ('IT', 'Avena sterilis L.', 'Avena maggiore, avena rossa', 'grano duro e tenero (trigo duro e trigo comum)', 'Inibidores da ACCasi (grupo A) — nomeado literalmente: ''Resistenza agli erbicidi inibitori dell''ACCasi (gruppo A)''.', 1992, array['Basilicata', 'Puglia', 'Sicilia', 'Veneto (casos esporadicos)', 'Emilia Romagna (casos esporadicos)', 'Marche (casos esporadicos)', 'Abruzzo (casos esporadicos)', 'Lazio (casos esporadicos)']::text[], true, 'GIRE (CNR-IPSP)', 'http://gire.mlib.cnr.it/index.php?sel=schedeSpecie/Avena', '''Alcune popolazioni risultano avere resistenza multipla agli inibitori dell''ALS.'' — GIRE (CNR), ficha Avena sterilis.', '2026-09-02T00:00:00Z') on conflict (pais, especie, mecanismo, cultura_declarada, autoridade) do nothing;
insert into public.resistencia_confirmada (pais, especie, especie_comum, cultura_declarada, mecanismo, primeiro_caso_ano, regioes, resistencia_multipla, autoridade, fonte_url, citacao_literal, capturado_em) values ('IT', 'Avena sterilis L.', 'Avena maggiore, avena rossa', 'grano duro e tenero (trigo duro e trigo comum) — a ficha nao separa a cultura por mecanismo; o ''Sistema colturale'' declarado para o bloco e este.', 'Inibidores da ALS — a ficha diz que ALGUMAS populacoes tem resistencia multipla aos inibidores da ALS: ''Alcune popolazioni risultano avere resistenza multipla agli inibitori dell''ALS.'' Existe tambem um mapa proprio rotulado ''Mappa (frumento) ALS''.', null, array['NAO SEI — a ficha lista regioes uma vez so, para o bloco inteiro, sem separar por mecanismo']::text[], true, 'GIRE (CNR-IPSP)', 'http://gire.mlib.cnr.it/index.php?sel=schedeSpecie/Avena', '''Alcune popolazioni risultano avere resistenza multipla agli inibitori dell''ALS.'' — GIRE (CNR), ficha Avena sterilis.', '2026-09-02T00:00:00Z') on conflict (pais, especie, mecanismo, cultura_declarada, autoridade) do nothing;
insert into public.resistencia_confirmada (pais, especie, especie_comum, cultura_declarada, mecanismo, primeiro_caso_ano, regioes, resistencia_multipla, autoridade, fonte_url, citacao_literal, capturado_em) values ('IT', 'Chenopodium album L.', 'Farinello comune', 'NAO SEI — a ficha nao declara sistema de cultivo para este caso.', 'Triazinas (atrazina), grupo C1 — nomeado literalmente: ''Popolazioni resistenti alle Triazine (atrazina) (gruppo C1)''. A ficha nao usa a palavra ''fotossistema''; usa o codigo de grupo C1.', 1982, array['Piemonte']::text[], true, 'GIRE (CNR-IPSP)', 'http://gire.mlib.cnr.it/index.php?sel=schedeSpecie/Chenopodium', '''Popolazioni resistenti alle Triazine (atrazina) (gruppo C1). Primi casi accertati: 1982.'' — GIRE (CNR), ficha Chenopodium album.', '2026-09-02T00:00:00Z') on conflict (pais, especie, mecanismo, cultura_declarada, autoridade) do nothing;
insert into public.resistencia_confirmada (pais, especie, especie_comum, cultura_declarada, mecanismo, primeiro_caso_ano, regioes, resistencia_multipla, autoridade, fonte_url, citacao_literal, capturado_em) values ('IT', 'Sinapis arvensis L.', 'Senape selvatica', 'grano duro e tenero (trigo duro e mole) — literal: "Sistema colturale: grano duro e tenero."', 'Inibidores da enzima ALS — literal: "Resistenza agli enzimi inibitori dell''ALS (gruppo B)"', 2006, array['Sicilia (tre casi) — literal: "Regioni interessate: Sicilia (tre casi) e Toscana (due casi)."', 'Toscana (due casi) — mesma frase literal acima']::text[], true, 'GIRE (CNR-IPSP)', 'http://gire.mlib.cnr.it/index.php?sel=schedeSpecie/Sinapis', '"Primo caso accertato nel 2006. Regioni interessate: Sicilia (tre casi) e Toscana (due casi)." (GIRE, ficha Sinapis arvensis, http://gire.mlib.cnr.it/index.php?sel=schedeSpecie/Sinapis)', '2026-09-02T00:00:00Z') on conflict (pais, especie, mecanismo, cultura_declarada, autoridade) do nothing;
insert into public.resistencia_confirmada (pais, especie, especie_comum, cultura_declarada, mecanismo, primeiro_caso_ano, regioes, resistencia_multipla, autoridade, fonte_url, citacao_literal, capturado_em) values ('IT', 'Solanum nigrum L.', 'Pomidorella, erba morella', 'mais (milho) — literal: "Sistema colturale: mais."', 'Triazinas (atrazina), grupo C1 — literal: "Resistenza alle triazine (atrazina) (gruppo C1)." OBSERVACAO DE LEI 4: a ficha NAO escreve a palavra "fotossistema". O que esta escrito no corpo e "triazine (atrazina)" e "gruppo C1". Nao afirmo o alvo bioquimico com palavras que a ficha nao usou.', 1978, array['Friuli Venezia-Giulia — literal: "Regioni interessate: Regioni interessate: Friuli Venezia-Giulia, Veneto, Trentino." (o texto da fonte repete "Regioni interessate:" duas vezes; e assim que sai da pagina)', 'Veneto — mesma frase literal acima', 'Trentino — mesma frase literal acima']::text[], true, 'GIRE (CNR-IPSP)', 'http://gire.mlib.cnr.it/index.php?sel=schedeSpecie/Solanum', '"Resistenza alle triazine (atrazina) (gruppo C1). Primo caso accertato nel 1978." (GIRE, ficha Solanum nigrum, http://gire.mlib.cnr.it/index.php?sel=schedeSpecie/Solanum)', '2026-09-02T00:00:00Z') on conflict (pais, especie, mecanismo, cultura_declarada, autoridade) do nothing;
insert into public.resistencia_confirmada (pais, especie, especie_comum, cultura_declarada, mecanismo, primeiro_caso_ano, regioes, resistencia_multipla, autoridade, fonte_url, citacao_literal, capturado_em) values ('IT', 'Sorghum halepense (L.) Pers.', 'Sorgo selvatico, sorghetta, melghetto', 'soia, pomodoro e melone (soja, tomate e melao) — literal: "Sistemi colturali: soia, pomodoro e melone." ATENCAO: a ficha lista os tres sistemas culturais em bloco, antes do tipo de resistencia; ela NAO diz em qual dos tres o primeiro caso de 2005 foi verificado. Nao sei a cultura especifica do primeiro caso.', 'Inibidores da enzima ACCasi, grupo A — literal: "Resistenza agli enzimi inibitori dell''ACCasi (gruppo A), bassi livelli di resistenza incrociata verso i DIM."', 2005, array['Lombardia — literal: "Regioni interessate: Lombardia." (unica regiao nomeada na ficha)']::text[], true, 'GIRE (CNR-IPSP)', 'http://gire.mlib.cnr.it/index.php?sel=schedeSpecie/Sorghum', '"bassi livelli di resistenza incrociata verso i DIM" (GIRE, ficha Sorghum halepense, http://gire.mlib.cnr.it/index.php?sel=schedeSpecie/Sorghum)', '2026-09-02T00:00:00Z') on conflict (pais, especie, mecanismo, cultura_declarada, autoridade) do nothing;
insert into public.resistencia_confirmada (pais, especie, especie_comum, cultura_declarada, mecanismo, primeiro_caso_ano, regioes, resistencia_multipla, autoridade, fonte_url, citacao_literal, capturado_em) values ('IT', 'Panicum dichotomiflorum Michx.', 'Panico delle risaie, panico dicotomifloro', 'riso (arroz)', 'ACCasi (inibidores da ACCase — gruppo A, 1 na nova classificacao HRAC)', 1978, array['Lombardia']::text[], true, 'GIRE (CNR-IPSP)', 'http://gire.mlib.cnr.it/index.php?sel=schedeSpecie/Panicum', '"Resistenza agli erbicidi inibitori dell''ACCasi (gruppo A, 1 nella nuova classificazione HRAC). Primo caso accertato nel 1978." — ficha GIRE de Panicum dichotomiflorum (gire.mlib.cnr.it, atualizacao declarada 26/08/2026)', '2026-09-02T00:00:00Z') on conflict (pais, especie, mecanismo, cultura_declarada, autoridade) do nothing;
insert into public.resistencia_confirmada (pais, especie, especie_comum, cultura_declarada, mecanismo, primeiro_caso_ano, regioes, resistencia_multipla, autoridade, fonte_url, citacao_literal, capturado_em) values ('IT', 'Papaver rhoeas L.', 'Papavero', 'grano duro e tenero (trigo duro e mole)', 'ALS (inibidores da ALS — gruppo B), ''in particolare alle solfoniluree'' (em particular as sulfonilureias)', 1998, array['Toscana', 'Lazio', 'Puglia', 'Basilicata', 'Sicilia', 'Veneto', 'Lombardia (1 caso)', 'Piemonte (1 caso)', 'Umbria (1 caso)']::text[], true, 'GIRE (CNR-IPSP)', 'http://gire.mlib.cnr.it/index.php?sel=schedeSpecie/Papaver', '"popolazioni con resistenza multipla agli inibitori dell''ALS (gruppo B) e al 2,4-D (grupo O). Primo caso accertato nel 1998." — ficha GIRE de Papaver rhoeas L. (gire.mlib.cnr.it, atualizacao declarada 26/08/2026)', '2026-09-02T00:00:00Z') on conflict (pais, especie, mecanismo, cultura_declarada, autoridade) do nothing;
