insert into public.resistencia_confirmada (pais, especie, especie_comum, cultura_declarada, mecanismo, primeiro_caso_ano, regioes, resistencia_multipla, autoridade, fonte_url, citacao_literal, capturado_em) values ('IT', 'Cyperus difformis L.', 'Zigolo delle risaie', 'Riso (arroz) — "Sistema colturale: riso."', 'ALS (gruppo B) — "erbicidi inibitori dell''ALS (gruppo B)"; mapa rotulado "Mappa (riso) ALS"', 1999, array['Piemonte', 'Lombardia', 'Emilia Romagna', 'Veneto', 'Sardegna']::text[], true, 'GIRE (CNR-IPSP)', 'http://gire.mlib.cnr.it/index.php?sel=schedeSpecie/Cyperus', '"con resistenza incrociata alle solfoniluree e alle triazolopirimidine. Primo caso accertato nel 1999." — ficha GIRE Cyperus difformis, secao Situazione della resistenza (http://gire.mlib.cnr.it/index.php?sel=schedeSpecie/Cyperus, ultima atualizacao declarada no rodape: 26/08/2026)', '2026-09-02T00:00:00Z') on conflict (pais, especie, mecanismo, cultura_declarada, autoridade) do nothing;
